// LogiPulse Content Pipeline: Filter (Last 7 Days), Clean, Categorize
const SEVEN_DAYS_MS = 7 * 24 * 60 * 60 * 1000;
const cutoffTime = Date.now() - SEVEN_DAYS_MS;

const items = $input.all();
const validArticles = [];
const seenUrls = new Set();

for (const item of items) {
  const raw = item.json;

  // 1. Date filter: Keep ONLY articles from the last 7 days
  const rawDate = raw.pubDate || raw.isoDate || raw.published;
  const pubTime = rawDate ? new Date(rawDate).getTime() : Date.now();

  if (isNaN(pubTime) || pubTime < cutoffTime) {
    continue; // Skip articles older than 7 days
  }

  // 2. Extract clean source URL & deduplicate within batch
  const sourceUrl = (raw.link || raw.guid || '').trim();
  if (!sourceUrl || seenUrls.has(sourceUrl)) {
    continue;
  }
  seenUrls.add(sourceUrl);

  // 3. Extract and clean Title & Source
  let title = (raw.title || '').trim();
  let source = 'Logistics News';

  // Google News RSS titles end with " - Publisher Name"
  if (title.includes(' - ')) {
    const parts = title.split(' - ');
    source = parts.pop().trim();
    title = parts.join(' - ').trim();
  }
  if (raw.source && typeof raw.source === 'string') {
    source = raw.source;
  }

  // Clean HTML tags from description/snippet
  let description = (raw.contentSnippet || raw.content || raw.description || '').trim();
  description = description.replace(/<[^>]*>?/gm, '').trim();

  // 4. Intelligent Category & Content Type Detection
  const combinedText = `${title} ${description}`.toLowerCase();
  let category = 'Logistics';
  let contentType = 'news';

  // Detect AI & Robotics
  if (/(ai|robot|autonomous|drone|computer vision|algorithm|machine learning|llm|automation|amr|agv|humanoid)/.test(combinedText)) {
    category = 'AI & Robotics';
    contentType = 'ai_insight';
  }
  // Detect Warehousing
  else if (/(warehouse|fulfillment|dark store|inventory|storage|pallet|forklift|cold storage|distribution center|racking)/.test(combinedText)) {
    category = 'Warehousing';
  }
  // Detect Shipping & Maritime
  else if (/(ship|ocean|maritime|port|container|vessel|dock|carrier|red sea|suez|terminal operator|drayage)/.test(combinedText)) {
    category = 'Shipping';
  }
  // Detect India Logistics
  else if (/(india|delhi|mumbai|gujarat|bengaluru|nagpur|dfc|nhai|railway|concor|bharatmala|ulip|sagarmala)/.test(combinedText)) {
    category = 'India';
  }
  // Detect Transportation & Fleet
  else if (/(truck|fleet|highway|electric truck|ev freight|intermodal|linehaul|rail freight|driver shortage)/.test(combinedText)) {
    category = 'Transportation';
  }
  // Detect Supply Chain Resiliency & Trade
  else if (/(supply chain|nearshore|reshoring|sourcing|procurement|tariff|supplier|lead time|shortage)/.test(combinedText)) {
    category = 'Supply Chain';
  }

  // Check if content indicates a market trend or metric benchmark
  if (/(surge|plunge|soar|record high|forecast|outlook|inflation|benchmark|growth rate|index|quarterly report|q1|q2|q3|q4)/.test(combinedText)) {
    if (contentType !== 'ai_insight') {
      contentType = 'trend';
    }
  }

  // 5. Select high quality representative imagery by category
  const fallbackImages = {
    'AI & Robotics': 'https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?auto=format&fit=crop&w=1200&q=80',
    'Warehousing': 'https://images.unsplash.com/photo-1553413077-190dd305871c?auto=format&fit=crop&w=1200&q=80',
    'Shipping': 'https://images.unsplash.com/photo-1542314831-068cd1dbfeeb?auto=format&fit=crop&w=1200&q=80',
    'Transportation': 'https://images.unsplash.com/photo-1601584115197-04ecc0da31d7?auto=format&fit=crop&w=1200&q=80',
    'India': 'https://images.unsplash.com/photo-1474487548417-781cb71495f3?auto=format&fit=crop&w=1200&q=80',
    'Supply Chain': 'https://images.unsplash.com/photo-1578575437130-527eed3abbec?auto=format&fit=crop&w=1200&q=80',
    'Logistics': 'https://images.unsplash.com/photo-1519003722824-194d4455a60c?auto=format&fit=crop&w=1200&q=80'
  };

  const imageUrl = raw.enclosure?.url || fallbackImages[category] || fallbackImages['Logistics'];

  validArticles.push({
    json: {
      title,
      description,
      source,
      source_url: sourceUrl,
      image_url: imageUrl,
      category,
      published_at: new Date(pubTime).toISOString(),
      content_type: contentType
    }
  });
}

return validArticles;

